async function eCompleteActivity(){try{await rpc('workflow.activities.complete',{id:$('eCompleteActivity').value,outcome:$('eActivityOutcome').value});notify('ปิดกิจกรรมแล้ว');await loadP0E();}catch(e){notify(e.message||e,true);}}
async function eSaveApplication(){try{const opp=(S.p0e.opportunities||[]).find(x=>x.id===$('eApplicationOpp').value);if(!opp)throw new Error('เลือก Opportunity');const r=await rpc('workflow.applications.save',{opportunityId:opp.id,insurerApplicationRef:$('eInsurerAppRef').value,productId:opp.productId,productVersionId:opp.productVersionId,sumAssured:Number(opp.sumAssured||0),premium:Number(opp.expectedAnnualPremium||0),premiumMode:'ANNUAL'});notify('สร้าง '+r.applicationNo+' แล้ว');await loadP0E();}catch(e){notify(e.message||e,true);}}
