async function dSaveNeeds(){try{if(!S.p0dNeeds)throw new Error('คำนวณ Needs ก่อน');const opp=(S.p0e.opportunities||[]).find(x=>x.id===$('dOpportunity').value);if(!opp||!opp.customerId)throw new Error('เลือก Opportunity ที่ผูก Customer ก่อน');const payload={opportunityId:opp.id,customerId:opp.customerId,incomeAnnual:Number($('dIncome').value),replacementYears:Number($('dYears').value),replacementDiscountRate:Number($('dDisc').value),debts:Number($('dDebt').value),mortgage:Number($('dMortgage').value),education:Number($('dEducation').value),funeralEmergency:Number($('dFinal').value),spouseSupport:Number($('dSpouse').value),otherNeeds:Number($('dOther').value),liquidAssets:Number($('dLiquid').value),existingInvestments:Number($('dInvest').value),existingCoverage:Number($('dExisting').value)};const r=await rpc('needs.saveAdvanced',payload);notify('บันทึก Needs '+r.id+' เข้า Workflow แล้ว');$('dSaveNeeds').disabled=true;await loadP0E();}catch(e){notify(e.message||e,true);}}


async function loadP1A(){try{if($('p1aRunRegression'))$('p1aRunRegression').disabled=!(S.user&&S.user.role==='admin');const d=await rpc('p1a.productionRates.status',{}),g=d.gate||{},rows=d.rows||[];$('p1aSummary').innerHTML='<div class="metrics-inline"><b>Operational Production:</b> '+esc(g.ready?'READY':'BLOCKED')+' &nbsp; <b>Exact official-public rows:</b> '+esc((d.classification||{}).officialPublicExactCount||0)+' &nbsp; <b>Final quote:</b> '+esc(g.finalQuoteReady?'READY':'NOT READY')+'</div>';$('p1aRates').innerHTML=table(rows,['product','version','useClass','sex','age','termYears','sumAssured','premiumMode','ratePer1000','annualPremium','rateStatus','sourceAgeDays','finalQuoteEligible']);$('p1aBoundary').innerHTML='<div class="notice '+(g.finalQuoteReady?'ok':'warn')+'">'+esc((d.classification||{}).statement||'')+'<br><b>Final quote versions:</b> '+esc((g.finalQuoteVersions||[]).join(', ')||'ไม่มี')+'<br><b>Preliminary versions:</b> '+esc((g.preliminaryRateVersions||[]).join(', ')||'ไม่มี')+'</div>'+(g.issues&&g.issues.length?'<pre>'+esc(g.issues.join('\n'))+'</pre>':'');if(g.latestRegression)$('p1aRegression').innerHTML='<div class="notice '+(g.latestRegression.failed?'error':'ok')+'">'+esc(g.latestRegression.runNo)+' · pass '+esc(g.latestRegression.passed)+' · fail '+esc(g.latestRegression.failed)+' · max diff '+esc(g.latestRegression.maxAbsDiff)+'<br><code>'+esc(g.latestRegression.basisHash||'')+'</code></div>';else $('p1aRegression').innerHTML='<div class="muted">ยังไม่มี ALL_PRODUCTION_ELIGIBLE regression run</div>';}catch(e){$('p1aSummary').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
async function p1aRunRegression(){const b=$('p1aRunRegression');b.disabled=true;$('p1aRegression').innerHTML='<span class="spinner"></span> กำลังทดสอบ Production rates…';try{const r=await rpc('admin.regression.run',{});$('p1aRegression').innerHTML='<div class="notice '+(r.failed?'error':'ok')+'">'+esc(r.scope||'')+' · '+esc(r.runNo)+' · PASS '+esc(r.passed)+'/'+esc(r.caseCount)+' · FAIL '+esc(r.failed)+' · max diff '+esc(r.maxAbsDiff)+'</div>';await Promise.all([loadP1A(),loadGate(),loadCatalog()]);}catch(e){$('p1aRegression').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}finally{b.disabled=false;}}


async function loadAnalyticsCatalog(){
  try{const d=await rpc('analytics.catalog',{});S.analytics.catalog=d.items||[];renderAnalyticsSelectors();if($('cmpAiStatus'))$('cmpAiStatus').textContent='AI: '+(d.ai&&d.ai.mode||'RULES_ONLY')+(d.ai&&d.ai.geminiConfigured?' · Gemini configured':' · deterministic fallback');}catch(e){if($('cmpResult'))$('cmpResult').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}
}
function renderAnalyticsSelectors(){const items=S.analytics.catalog||[];if($('cmpProducts'))$('cmpProducts').innerHTML=items.length?items.map(x=>'<label class="choice-row"><input type="checkbox" name="cmpProduct" value="'+escAttr(x.productVersionId)+'"><span><b>'+esc(x.insurer||'-')+'</b> · '+esc(x.product||x.productVersionId)+' <span class="muted">v'+esc(x.version||'')+'</span></span><span class="quality">'+esc(x.dataQuality||'')+'</span></label>').join(''):'<p class="muted">ยังไม่มีผลิตภัณฑ์</p>';const opts=items.map(x=>'<option value="'+escAttr(x.productVersionId)+'">'+esc((x.insurer||'-')+' · '+(x.product||x.productVersionId)+' · v'+(x.version||''))+'</option>').join('');if($('valProduct'))$('valProduct').innerHTML=opts;}
function analyticsInput(prefix){return {age:Number($(prefix+'Age').value),sex:$(prefix+'Sex').value,termYears:Number($(prefix+'Term').value),sumAssured:Number($(prefix+'Sum').value),premiumMode:$(prefix+'Mode').value,discountRate:Number($(prefix+'Discount').value||.02)};}
async function cmpRun(){const ids=Array.from(document.querySelectorAll('input[name="cmpProduct"]:checked')).map(x=>x.value);if(ids.length<1)return notify('เลือกอย่างน้อย 1 แบบประกัน',true);if(ids.length>8)return notify('เลือกได้สูงสุด 8 แบบ',true);$('cmpResult').innerHTML='<span class="spinner"></span> กำลังวิเคราะห์…';try{const r=await rpc('analytics.compare',Object.assign(analyticsInput('cmp'),{productVersionIds:ids}));S.analytics.comparison=r;const rows=(r.results||[]).map(x=>x.ok?{'บริษัท':x.insurer,'แบบประกัน':x.product,'คุณภาพข้อมูล':x.dataQuality,'เบี้ย/ปี':fmtMaybe(x.annualPremium),'เบี้ยรวม':fmtMaybe(x.totalPremium),'ผลประโยชน์เงินสดรวม':fmtMaybe(x.totalLivingBenefits),'สุทธิเมื่อครบสัญญา':fmtMaybe(x.maturityNet),'IRR':pctMaybe(x.irrAnnual),'คุ้มทุนเวนคืนปี':x.breakEvenSurrenderYear==null?'N/A':x.breakEvenSurrenderYear,'ทุนเสียชีวิตสูงสุด':fmtMaybe(x.maxDeathBenefit)}:{'บริษัท':'','แบบประกัน':x.productVersionId,'คุณภาพข้อมูล':'ERROR','เบี้ย/ปี':'N/A','เบี้ยรวม':'N/A','ผลประโยชน์เงินสดรวม':'N/A','สุทธิเมื่อครบสัญญา':'N/A','IRR':'N/A','คุ้มทุนเวนคืนปี':'N/A','ทุนเสียชีวิตสูงสุด':x.error});$('cmpResult').innerHTML=table(rows,['บริษัท','แบบประกัน','คุณภาพข้อมูล','เบี้ย/ปี','เบี้ยรวม','ผลประโยชน์เงินสดรวม','สุทธิเมื่อครบสัญญา','IRR','คุ้มทุนเวนคืนปี','ทุนเสียชีวิตสูงสุด'])+'<p class="muted">'+esc(r.disclaimer||'')+'</p>';drawComparisonChart(r);$('cmpAi').disabled=false;}catch(e){$('cmpResult').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
function fmtMaybe(v){return v==null||v===''?'N/A':money(v)}function pctMaybe(v){return v==null||v===''?'N/A':(Number(v)*100).toFixed(3)+'%'}
function drawComparisonChart(r){const items=(r.results||[]).filter(x=>x.ok);drawBarChart('cmpChart',items.map(x=>x.insurer+'\n'+x.product),[{name:'เบี้ยรวม',values:items.map(x=>x.totalPremium)},{name:'ผลประโยชน์เงินสดรวม',values:items.map(x=>x.totalLivingBenefits)},{name:'สุทธิครบสัญญา',values:items.map(x=>x.maturityNet)}]);}
async function cmpAi(){if(!S.analytics.comparison)return;try{$('cmpAiResult').textContent='กำลังวิเคราะห์…';const r=await rpc('analytics.ai',{analysisType:'COMPARISON',comparisonRunNo:S.analytics.comparison.runNo});$('cmpAiResult').textContent=r.text+'\n\nEngine: '+r.engine+(r.model?' / '+r.model:'');}catch(e){$('cmpAiResult').textContent=e.message||e;}}
async function valRun(){if(!$('valProduct').value)return notify('เลือกแบบประกัน',true);$('valSummary').innerHTML='<span class="spinner"></span> กำลังวิเคราะห์…';try{const r=await rpc('analytics.policyValue',Object.assign(analyticsInput('val'),{productVersionId:$('valProduct').value}));S.analytics.policyValue=r;const st=r.stayToMaturity||{};$('valSummary').innerHTML='<div class="grid">'+card('เบี้ยรวม',fmtMaybe(st.totalPremium))+card('ผลประโยชน์เงินสดรวม',fmtMaybe(st.totalLivingBenefits))+card('สุทธิเมื่ออยู่ครบ',fmtMaybe(st.netLivingAtMaturity))+card('IRR',pctMaybe(st.irrAnnual))+card('คุ้มทุนเวนคืน',st.breakEvenSurrenderYear==null?'N/A':'ปี '+st.breakEvenSurrenderYear)+card('ทุนเสียชีวิตสูงสุด',fmtMaybe(st.maxDeathBenefit))+'</div><p class="muted">'+esc(r.disclaimer||'')+'</p>';$('valTable').innerHTML=table((r.rows||[]).map(x=>({'ปี':x.policyYear,'อายุ':x.age,'เบี้ยสะสม':fmtMaybe(x.premiumsPaid),'เงินสดรับแล้ว':fmtMaybe(x.livingBenefitsReceived),'เวนคืน':fmtMaybe(x.surrenderValue),'สุทธิถ้าเวนคืน':fmtMaybe(x.surrenderNet),'ทุน Paid-up':fmtMaybe(x.paidUpSumAssured),'ผลครบกำหนด Paid-up':fmtMaybe(x.paidUpMaturityBenefit),'สุทธิ Paid-up':fmtMaybe(x.paidUpNet),'ทุน Extended Term':fmtMaybe(x.extendedTermSumAssured),'ระยะ Extended':x.extendedTermYears==null?'N/A':x.extendedTermYears+'y '+(x.extendedTermMonths||0)+'m','สุทธิ Extended':fmtMaybe(x.extendedNet)})),['ปี','อายุ','เบี้ยสะสม','เงินสดรับแล้ว','เวนคืน','สุทธิถ้าเวนคืน','ทุน Paid-up','ผลครบกำหนด Paid-up','สุทธิ Paid-up','ทุน Extended Term','ระยะ Extended','สุทธิ Extended']);drawValueChart(r);$('valAi').disabled=false;}catch(e){$('valSummary').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
function drawValueChart(r){const rows=r.rows||[];drawLineChart('valChart',rows.map(x=>'Y'+x.policyYear),[{name:'เบี้ยสะสม',values:rows.map(x=>x.premiumsPaid)},{name:'มูลค่าเวนคืน',values:rows.map(x=>x.surrenderValue)},{name:'สุทธิถ้าเวนคืน',values:rows.map(x=>x.surrenderNet)},{name:'Paid-up maturity',values:rows.map(x=>x.paidUpMaturityBenefit)}]);}
async function valAi(){if(!S.analytics.policyValue)return;try{$('valAiResult').textContent='กำลังวิเคราะห์…';const r=await rpc('analytics.ai',{analysisType:'POLICY_VALUE',policyAnalysisNo:S.analytics.policyValue.analysisNo});$('valAiResult').textContent=r.text+'\n\nEngine: '+r.engine+(r.model?' / '+r.model:'');}catch(e){$('valAiResult').textContent=e.message||e;}}
function drawBarChart(id,labels,series){drawCanvasChart(id,labels,series,'bar')}function drawLineChart(id,labels,series){drawCanvasChart(id,labels,series,'line')}
function drawCanvasChart(id,labels,series,type){const c=$(id);if(!c)return;const rect=c.parentElement.getBoundingClientRect();c.width=Math.max(640,Math.floor(rect.width*devicePixelRatio));c.height=Math.floor(340*devicePixelRatio);const ctx=c.getContext('2d');ctx.scale(devicePixelRatio,devicePixelRatio);const W=c.width/devicePixelRatio,H=c.height/devicePixelRatio,p={l:62,r:18,t:30,b:64};ctx.clearRect(0,0,W,H);const vals=[];series.forEach(s=>(s.values||[]).forEach(v=>{if(v!=null&&v!==''&&Number.isFinite(Number(v)))vals.push(Number(v))}));let min=Math.min(0,...vals),max=Math.max(1,...vals);if(max===min)max=min+1;const y=v=>p.t+(max-Number(v))/(max-min)*(H-p.t-p.b),x=i=>p.l+(i+.5)*(W-p.l-p.r)/Math.max(1,labels.length);ctx.strokeStyle='#cbd5e1';ctx.lineWidth=1;for(let k=0;k<=5;k++){const yy=p.t+k*(H-p.t-p.b)/5;ctx.beginPath();ctx.moveTo(p.l,yy);ctx.lineTo(W-p.r,yy);ctx.stroke();const value=max-(max-min)*k/5;ctx.fillStyle='#64748b';ctx.font='11px system-ui';ctx.fillText(new Intl.NumberFormat('th-TH',{notation:'compact',maximumFractionDigits:1}).format(value),4,yy+4)}const palette=['#174ea6','#0f9d58','#f9ab00','#a142f4','#d93025','#00897b'];series.forEach((s,si)=>{ctx.strokeStyle=palette[si%palette.length];ctx.fillStyle=palette[si%palette.length];ctx.lineWidth=2;if(type==='line'){ctx.beginPath();let started=false;(s.values||[]).forEach((v,i)=>{if(v==null||v===''||!Number.isFinite(Number(v)))return;const xx=x(i),yy=y(v);started?ctx.lineTo(xx,yy):(ctx.moveTo(xx,yy),started=true);ctx.fillRect(xx-2,yy-2,4,4)});ctx.stroke()}else{const group=(W-p.l-p.r)/Math.max(1,labels.length),bw=Math.max(6,group/(series.length+1));(s.values||[]).forEach((v,i)=>{if(v==null||v===''||!Number.isFinite(Number(v)))return;const xx=p.l+i*group+bw*(si+.5),yy=y(v),base=y(0);ctx.fillRect(xx,Math.min(yy,base),bw*.8,Math.abs(base-yy))})}ctx.fillRect(p.l+si*150,p.t-22,12,12);ctx.fillStyle='#334155';ctx.fillText(s.name,p.l+16+si*150,p.t-12)});ctx.save();ctx.translate(0,H-p.b+18);labels.forEach((lab,i)=>{ctx.fillStyle='#475569';ctx.font='10px system-ui';ctx.textAlign='center';ctx.fillText(String(lab).slice(0,20),x(i),0)});ctx.restore();}

async function loadProductAdmin(){if(!S.user||!['admin','manager'].includes(S.user.role)){if($('dbInfo'))$('dbInfo').innerHTML='<div class="notice error">เฉพาะ admin/manager</div>';return;}try{const [info,d,rb]=await Promise.all([rpc('database.info',{}),rpc('admin.productAdmin.list',{}),rpc('admin.ratebooks.list',{})]);S.adminData={insurers:d.insurers||[],products:d.products||[],versions:d.versions||[],rateBooks:rb.items||[]};$('dbInfo').innerHTML='<b>'+esc(info.name)+'</b><br><code>'+esc(info.spreadsheetId)+'</code><br><span class="muted">AI '+esc(info.ai.mode)+' · '+esc(info.ai.model)+'</span>';$('admInsurers').innerHTML=table(S.adminData.insurers,['code','shortName','nameTh','website','sourceRef','active']);$('admProducts').innerHTML=table(S.adminData.products.map(p=>({code:p.code,name:p.name,insurerName:p.insurerName,category:p.category,active:p.active})),['code','name','insurerName','category','active']);$('admRateBooks').innerHTML=table(S.adminData.rateBooks,['bookCode','title','version','status','sourceRef','approvalRef','effectiveFrom','effectiveTo']);refreshAdminSelectors();}catch(e){$('dbInfo').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
function refreshAdminSelectors(){const ins=S.adminData.insurers||[];$('admProductInsurer').innerHTML=ins.map(x=>'<option value="'+escAttr(x.id)+'">'+esc(x.shortName||x.nameTh)+'</option>').join('');const prodBy={};(S.adminData.products||[]).forEach(x=>prodBy[x.id]=x);$('admRbProduct').innerHTML=(S.adminData.versions||[]).map(v=>'<option value="'+escAttr(v.id)+'" data-product="'+escAttr(v.productId)+'">'+esc((prodBy[v.productId]&&prodBy[v.productId].name||v.productId)+' · v'+v.version)+'</option>').join('');const rbo=(S.adminData.rateBooks||[]).map(x=>'<option value="'+escAttr(x.id)+'">'+esc(x.bookCode+' · '+x.title)+'</option>').join('');$('admImportBook').innerHTML=rbo;$('admSheetBook').innerHTML=rbo;}
async function admSaveInsurer(){try{await rpc('admin.insurers.save',{id:$('admInsurerId').value,code:$('admInsurerCode').value,nameTh:$('admInsurerName').value,shortName:$('admInsurerShort').value,website:$('admInsurerWebsite').value,sourceRef:$('admInsurerSource').value});notify('บันทึกบริษัทแล้ว');await Promise.all([loadProductAdmin(),loadAnalyticsCatalog()]);}catch(e){notify(e.message||e,true)}}
async function admSaveProduct(){try{await rpc('admin.productAdmin.save',{productId:$('admProductId').value,productVersionId:$('admVersionId').value,insurerId:$('admProductInsurer').value,productCode:$('admProductCode').value,productName:$('admProductName').value,category:$('admCategory').value,version:$('admVersion').value,pricingMode:$('admPricingMode').value,status:$('admVersionStatus').value,premiumPayYears:Number($('admPayYears').value),effectiveFrom:$('admEffectiveFrom').value,effectiveTo:$('admEffectiveTo').value,rateTableCode:$('admRateTableCode').value,sourceRef:$('admProductSource').value,approvalRef:$('admApprovalRef').value,premiumModes:'ANNUAL'});notify('บันทึกแบบประกันแล้ว');await Promise.all([loadProductAdmin(),loadAnalyticsCatalog()]);}catch(e){notify(e.message||e,true)}}
async function admSaveRateBook(){try{const pv=(S.adminData.versions||[]).find(v=>v.id===$('admRbProduct').value);if(!pv)throw new Error('เลือก Product Version');const p=(S.adminData.products||[]).find(x=>x.id===pv.productId);if(!p)throw new Error('ไม่พบ Product');await rpc('admin.ratebooks.save',{id:$('admRateBookId').value,bookCode:$('admRbCode').value,insurerId:p.insurerId,productId:p.id,productVersionId:pv.id,title:$('admRbTitle').value,version:$('admRbVersion').value,status:$('admRbStatus').value,sourceRef:$('admRbSource').value,effectiveFrom:$('admRbFrom').value,effectiveTo:$('admRbTo').value,approvalRef:$('admRbApproval').value,currency:'THB'});notify('บันทึก Rate Book แล้ว');await loadProductAdmin();}catch(e){notify(e.message||e,true)}}
async function readCsvFileInput(id){const f=$(id).files&&$(id).files[0];if(!f)throw new Error('เลือกไฟล์ CSV');const text=await f.text();return {file:f,rows:parseCsv(text),hash:await sha256File(f)}}
async function admValidateRate(){try{const d=await readCsvFileInput('admRateFile');const r=await rpc('admin.ratebooks.validate',{rateBookId:$('admImportBook').value,rows:d.rows,fileName:d.file.name,fileSha256:d.hash});S.rateImport={...d,validation:r,rateBookId:$('admImportBook').value};$('admRateImportResult').innerHTML='<div class="notice '+(r.ok?'ok':'error')+'">Rows '+esc(r.rowCount)+' · Premium '+esc(r.summary.premium)+' · Policy Value '+esc(r.summary.policyValue)+' · Benefit '+esc(r.summary.benefit)+'<br>'+esc((r.errors||[]).join(' | ')||'VALID')+'</div>';$('admCommitRate').disabled=!r.ok;}catch(e){$('admRateImportResult').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
async function admCommitRate(){if(!S.rateImport)return;try{const d=S.rateImport,r=await rpc('admin.ratebooks.import',{rateBookId:d.rateBookId,rows:d.rows,fileName:d.file.name,fileSha256:d.hash,validationHash:d.validation.validationHash});$('admRateImportResult').innerHTML='<div class="notice ok">Commit สำเร็จ · premium '+esc(r.saved.premium)+' · policy value '+esc(r.saved.policyValue)+' · benefit '+esc(r.saved.benefit)+'</div>';$('admCommitRate').disabled=true;await Promise.all([loadProductAdmin(),loadAnalyticsCatalog()]);}catch(e){$('admRateImportResult').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
async function admSheetImport(validateOnly){try{const r=await rpc('admin.ratebooks.importSheet',{rateBookId:$('admSheetBook').value,spreadsheetId:$('admSourceSpreadsheet').value,sheetName:$('admSourceSheet').value,validateOnly});$('admSheetImportResult').innerHTML='<div class="notice '+((r.ok!==false)?'ok':'error')+'">'+esc(validateOnly?'Validation complete':'Import complete')+'<pre>'+esc(JSON.stringify(r.summary||r.saved||r,null,2))+'</pre></div>';if(!validateOnly)await Promise.all([loadProductAdmin(),loadAnalyticsCatalog()]);}catch(e){$('admSheetImportResult').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
async function loadUsersAdmin(){if(!S.user||S.user.role!=='admin'){notify('เฉพาะ Admin',true);nav('dashboard');return;}try{const d=await rpc('admin.users.list',{});S.userAdmin=d;const items=d.items||[];$('usrTotal').textContent=items.length;$('usrActive').textContent=items.filter(x=>x.active).length;$('usrAdmins').textContent=items.filter(x=>x.active&&x.role==='admin').length;$('usrMustChange').textContent=items.filter(x=>x.mustChangePassword).length;const rows=items.map(x=>({email:x.email,name:x.name,role:x.role,active:x.active?'ใช้งาน':'ปิด',mustChangePassword:x.mustChangePassword?'ต้องเปลี่ยน':'',lastLoginAt:x.lastLoginAt||'',action:'<button class="btn ghost usr-edit" data-id="'+escAttr(x.id)+'">แก้ไข</button> <button class="btn ghost usr-reset" data-id="'+escAttr(x.id)+'">รีเซ็ตรหัส</button> <button class="btn ghost usr-revoke" data-id="'+escAttr(x.id)+'">ออกจากระบบทุกเครื่อง</button>'}));$('usrTable').innerHTML=htmlTableRaw(rows,['email','name','role','active','mustChangePassword','lastLoginAt','action']);document.querySelectorAll('.usr-edit').forEach(b=>b.onclick=()=>editUserForm(b.dataset.id));document.querySelectorAll('.usr-reset').forEach(b=>b.onclick=()=>resetUserPassword(b.dataset.id));document.querySelectorAll('.usr-revoke').forEach(b=>b.onclick=()=>revokeUserSessions(b.dataset.id));$('usrRoleMatrix').innerHTML=table((d.roles||[]).map(r=>({role:r.role,permissions:(r.permissions||[]).join(', ')})),['role','permissions']);}catch(e){$('usrTable').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
function htmlTableRaw(rows,cols){if(!rows.length)return '<div class="muted">ไม่พบข้อมูล</div>';return '<div class="tablewrap"><table><thead><tr>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+(c==='action'?String(r[c]||''):esc(r[c]??''))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function clearUserForm(){$('usrId').value='';$('usrEmail').value='';$('usrName').value='';$('usrRole').value='agent';$('usrActiveSelect').value='TRUE';$('usrTempPassword').value='';$('usrTempWrap').classList.remove('hidden');$('usrFormMsg').innerHTML='';}
function editUserForm(id){const u=(S.userAdmin.items||[]).find(x=>x.id===id);if(!u)return;$('usrId').value=u.id;$('usrEmail').value=u.email;$('usrName').value=u.name;$('usrRole').value=u.role;$('usrActiveSelect').value=u.active?'TRUE':'FALSE';$('usrTempPassword').value='';$('usrTempWrap').classList.add('hidden');window.scrollTo({top:0,behavior:'smooth'});}
async function saveAdminUser(){try{const id=$('usrId').value,p={id,email:$('usrEmail').value,name:$('usrName').value,role:$('usrRole').value,active:$('usrActiveSelect').value==='TRUE'};if(!id)p.temporaryPassword=$('usrTempPassword').value;const r=await rpc('admin.users.save',p);$('usrFormMsg').innerHTML='<div class="notice ok">'+esc(r.created?'สร้างผู้ใช้แล้ว และบังคับเปลี่ยนรหัสผ่านครั้งแรก':'อัปเดตผู้ใช้แล้ว')+'</div>';clearUserForm();await loadUsersAdmin();}catch(e){$('usrFormMsg').innerHTML='<div class="notice error">'+esc(e.message||e)+'</div>';}}
async function resetUserPassword(id){const typed=prompt('กำหนดรหัสผ่านชั่วคราวใหม่ (เว้นว่างให้ระบบสุ่มอัตโนมัติ)')??null;if(typed===null)return;try{const r=await rpc('admin.users.resetPassword',{id,newPassword:typed});const text=r.temporaryPassword?'รหัสผ่านชั่วคราว: '+r.temporaryPassword+'\n\nโปรดส่งให้ผู้ใช้ผ่านช่องทางที่ปลอดภัย และผู้ใช้จะถูกบังคับเปลี่ยนเมื่อเข้าสู่ระบบ':'รีเซ็ตรหัสผ่านสำเร็จ ผู้ใช้จะถูกบังคับเปลี่ยนเมื่อเข้าสู่ระบบ';alert(text);await loadUsersAdmin();}catch(e){notify(e.message||e,true)}}
async function revokeUserSessions(id){if(!confirm('ให้ออกจากระบบทุกอุปกรณ์ของผู้ใช้นี้หรือไม่?'))return;try{const r=await rpc('admin.users.revokeSessions',{id});notify('เพิกถอน '+r.revokedSessions+' session แล้ว');await loadUsersAdmin();}catch(e){notify(e.message||e,true)}}
